// ── DESIGN TOKENS ─────────────────────────────────────────────────────────────
const DS = `
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  /* Surfaces */
  --s1: #F5F6F8;
  --s2: #FFFFFF;
  --s3: #F9FAFB;
  --s4: #F3F4F6;

  /* Borders */
  --b1: #F3F4F6;
  --b2: #E5E7EB;
  --b3: #D1D5DB;

  /* Brand, Coral */
  --brand:    #F2416A;
  --brand-hv: #E0305A;
  --brand-lo: rgba(242,65,106,0.07);
  --brand-md: rgba(242,65,106,0.16);

  /* Success */
  --green:    #059669;
  --green-lo: rgba(5,150,105,0.07);
  --green-md: rgba(5,150,105,0.16);

  /* Warning */
  --amber:    #D97706;
  --amber-lo: rgba(217,119,6,0.07);
  --amber-md: rgba(217,119,6,0.16);

  /* Danger */
  --red:    #E11D48;
  --red-lo: rgba(225,29,72,0.07);
  --red-md: rgba(225,29,72,0.16);

  /* Text, t4 only for decorative/disabled, t3 for labels */
  --t1: #111827;
  --t2: #374151;
  --t3: #6B7280;
  --t4: #9CA3AF;

  /* Type scale, 5 sizes only */
  --tx-xs:   11px;
  --tx-sm:   12px;
  --tx-base: 13px;
  --tx-md:   15px;
  --tx-lg:   20px;

  /* Typography */
  --f:  'Inter', system-ui, sans-serif;
  --fm: 'Inter', system-ui, sans-serif;

  /* Dark video surface tokens */
  --vid-bg:      #0d1117;
  --vid-surface: #1a2235;
  --vid-border:  #2d3748;
  --vid-muted:   #6b7280;

  /* Radius */
  --r-sm: 6px;
  --r:    10px;
  --r-lg: 14px;

  /* Motion, structural vs reactive */
  --ease:           cubic-bezier(0.16, 1, 0.3, 1);
  --fast:           0.15s;
  --mid:            0.22s;
  --structural:     0.35s;  /* cards loading in */
  --reactive:       0.1s;   /* AI suggestions appearing */
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: var(--f); background: var(--s1); color: var(--t1); font-size: var(--tx-base); line-height: 1.5; -webkit-font-smoothing: antialiased; }
::-webkit-scrollbar { width: 4px; }
::-webkit-scrollbar-thumb { background: var(--b3); border-radius: 2px; }

/* Focus rings, accessibility */
:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; border-radius: var(--r-sm); }
button:focus-visible, a:focus-visible { outline: 2px solid var(--brand); outline-offset: 2px; }

.ds-input {
  width: 100%; background: #fff; border: 1px solid var(--b2);
  border-radius: var(--r-sm); color: var(--t1); font-family: var(--f);
  font-size: var(--tx-base); padding: 9px 12px; outline: none;
  transition: border-color var(--fast), box-shadow var(--fast); line-height: 1.6;
}
.ds-input:focus { border-color: var(--brand); box-shadow: 0 0 0 3px var(--brand-lo); }
.ds-input::placeholder { color: var(--t3); }

.ds-btn {
  display: inline-flex; align-items: center; gap: 6px;
  border-radius: var(--r-sm); font-family: var(--f); font-size: var(--tx-base); font-weight: 500;
  padding: 8px 15px; border: 1px solid transparent;
  cursor: pointer; white-space: nowrap; line-height: 1; transition: all var(--fast);
}
.ds-btn:disabled { opacity: 0.42; cursor: not-allowed; }
.ds-btn:active:not(:disabled) { transform: scale(0.97); }
.ds-btn-primary   { background: var(--brand); color: #fff; border-color: var(--brand); }
.ds-btn-primary:not(:disabled):hover { background: var(--brand-hv); border-color: var(--brand-hv); }
.ds-btn-secondary { background: var(--brand-lo); color: var(--brand); border-color: var(--brand-md); }
.ds-btn-secondary:not(:disabled):hover { background: var(--brand-md); }
.ds-btn-ghost     { background: #fff; color: var(--t2); border-color: var(--b2); }
.ds-btn-ghost:not(:disabled):hover { color: var(--t1); border-color: var(--b3); background: var(--s4); }
.ds-btn-danger    { background: var(--red-lo); color: var(--red); border-color: var(--red-md); }
.ds-btn-danger:not(:disabled):hover { background: var(--red-md); }

/* Nav link */
.nav-link { font-size: var(--tx-md); color: var(--t3); cursor: pointer; padding: 4px 2px; transition: color var(--fast); border-bottom: 2px solid transparent; font-weight: 500; }
.nav-link:hover { color: var(--t1); }
.nav-link.active { color: var(--t1); border-bottom-color: var(--brand); }

/* Framework card, top accent bar selected state */
.fw-card { border: 1px solid var(--b2); border-radius: var(--r); padding: 14px; cursor: pointer; transition: all var(--fast); background: #fff; position: relative; overflow: hidden; }
.fw-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 0; background: var(--t1); border-radius: var(--r) var(--r) 0 0; transition: height var(--fast); }
.fw-card:hover { border-color: var(--b3); background: var(--s3); }
.fw-card.selected { border-color: var(--b3); background: var(--s4); }
.fw-card.selected::before { height: 3px; }

/* Empty state */
.ds-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 20px 12px; gap: 8px; }
.ds-empty-icon { width: 36px; height: 36px; border-radius: 50%; background: var(--s4); display: flex; align-items: center; justify-content: center; }
.ds-empty-title { font-size: var(--tx-sm); font-weight: 600; color: var(--t2); }
.ds-empty-sub { font-size: var(--tx-xs); color: var(--t3); text-align: center; line-height: 1.6; font-family: var(--fm); }

/* Suggestion hover */
.ds-suggestion { transition: background var(--reactive); }
.ds-suggestion:hover { background: var(--brand-lo) !important; cursor: pointer; }

/* Inconsistency alert flash */
.ds-flag-new { animation: flag-flash 1.2s var(--ease) both; }
@keyframes flag-flash { 0% { background: rgba(217,119,6,0.22); } 100% { background: var(--amber-lo); } }

/* Range slider */
input[type=range] { appearance: none; background: transparent; border: none; padding: 0; cursor: pointer; width: 100%; }
input[type=range]::-webkit-slider-runnable-track { height: 3px; border-radius: 2px; background: var(--b2); }
input[type=range]::-webkit-slider-thumb { appearance: none; width: 14px; height: 14px; border-radius: 50%; background: var(--brand); margin-top: -5.5px; transition: transform var(--fast); box-shadow: 0 1px 4px var(--brand-md); }
input[type=range]::-webkit-slider-thumb:hover { transform: scale(1.3); }

@keyframes ds-spin   { to { transform: rotate(360deg); } }
@keyframes ds-pulse  { 0%,100% { opacity:1; transform:scale(1); } 50% { opacity:0.45; transform:scale(0.8); } }
@keyframes ds-fadein { from { opacity:0; transform:translateY(6px); } to { opacity:1; transform:translateY(0); } }
.ds-fadein { animation: ds-fadein 0.3s var(--ease) both; }
`;

