// ── PRIMITIVES ────────────────────────────────────────────────────────────────
function Spinner({ size = 13, color }) {
  return <div style={{ width: size, height: size, border: "2px solid transparent", borderTopColor: color || "var(--brand)", borderRadius: "50%", animation: "ds-spin 0.65s linear infinite", flexShrink: 0 }} />;
}
function Btn({ children, onClick, variant = "primary", disabled, size, style = {} }) {
  const sz = size === "sm" ? { padding: "5px 11px", fontSize: 11 } : size === "lg" ? { padding: "11px 24px", fontSize: 14 } : {};
  return <button className={`ds-btn ds-btn-${variant}`} onClick={disabled ? undefined : onClick} disabled={!!disabled} style={{ ...sz, ...style }}>{children}</button>;
}
function Card({ children, style = {} }) {
  return <div style={{ background: "var(--s2)", border: "1px solid var(--b2)", borderRadius: "var(--r)", padding: 18, ...style }}>{children}</div>;
}
function SectionMark({ children, color, right }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 14 }}>
      <div style={{ fontSize: 10, fontFamily: "var(--fm)", letterSpacing: "0.12em", textTransform: "uppercase", color: color || "var(--t4)", fontWeight: 500 }}>{children}</div>
      {right}
    </div>
  );
}
function GradBar({ pct }) {
  const g = pct >= 70 ? "linear-gradient(90deg,#059669,#34d399)" : pct >= 40 ? "linear-gradient(90deg,#b45309,#fbbf24)" : "linear-gradient(90deg,#9f1239,#fb7185)";
  const tc = pct >= 70 ? "var(--green)" : pct >= 40 ? "var(--amber)" : "var(--red)";
  return { bar: <div style={{ height: 4, background: "var(--b2)", borderRadius: 2, overflow: "hidden" }}><div style={{ height: "100%", width: `${pct}%`, background: g, borderRadius: 2, transition: "width 0.75s var(--ease)" }} /></div>, color: tc };
}
function Chip({ label, onRemove }) {
  return (
    <span style={{ display: "inline-flex", alignItems: "center", gap: 4, padding: "4px 10px", background: "var(--s4)", border: "1px solid var(--b2)", borderRadius: 99, fontSize: 12, color: "var(--t2)", fontWeight: 400 }}>
      {label}
      {onRemove && <button onClick={onRemove} style={{ background: "none", border: "none", color: "var(--t4)", cursor: "pointer", fontSize: 15, lineHeight: 1, padding: 0, display: "flex" }}>×</button>}
    </span>
  );
}
function LiveDot() {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
      <div style={{ width: 7, height: 7, borderRadius: "50%", background: "var(--red)", animation: "ds-pulse 1.3s ease-in-out infinite" }} />
      <span style={{ fontSize: 10, fontFamily: "var(--fm)", color: "var(--red)", letterSpacing: "0.12em", fontWeight: 500 }}>LIVE</span>
    </div>
  );
}

