// ── SCORE RING ────────────────────────────────────────────────────────────────

// ── SCORE RING ────────────────────────────────────────────────────────────────
function ScoreRing({ score, max = 10, color }) {
  const r = 30, circ = 2 * Math.PI * r;
  return (
    <svg width="80" height="80" viewBox="0 0 80 80" style={{ flexShrink: 0 }}>
      <circle cx="40" cy="40" r={r} fill="none" stroke="#E5E7EB" strokeWidth="7" />
      <circle cx="40" cy="40" r={r} fill="none" stroke={color} strokeWidth="7"
        strokeLinecap="round"
        strokeDasharray={`${circ * (score / max)} ${circ}`}
        transform="rotate(-90 40 40)"
        style={{ transition: "stroke-dasharray 0.9s var(--ease)" }}
      />
      <text x="40" y="40" textAnchor="middle" dominantBaseline="central" fontSize="24" fontWeight="700" fontFamily="var(--fm)" fill={color}>{score}</text>
    </svg>
  );
}

// ── TRANSCRIPT VIEW ───────────────────────────────────────────────────────────
function TranscriptView({ text, flaggedPhrases, transcriptRef }) {
  const turns = text.split(/\n\n+/).filter(Boolean);
  return (
    <div ref={transcriptRef} style={{ flex: 1, overflowY: "auto", padding: "10px 14px" }}>
      {turns.length === 0 && (
        <div style={{ color: "var(--t4)", fontSize: 11, fontStyle: "italic", padding: "6px 0" }}>
          Transcript appears here as the interview progresses...
        </div>
      )}
      {turns.map((turn, i) => {
        const colonIdx = turn.indexOf(":");
        if (colonIdx === -1) return null;
        const speaker = turn.slice(0, colonIdx).trim();
        const body = turn.slice(colonIdx + 1).trim();
        const isPaul = speaker === "Paul";
        const flagged = flaggedPhrases.length > 0 && flaggedPhrases.some(p => p && turn.toLowerCase().includes(p.toLowerCase()));
        return (
          <div key={i} style={{ marginBottom: 10, padding: flagged ? "6px 8px 6px 10px" : "2px 0", background: flagged ? "rgba(217,119,6,0.07)" : "transparent", borderLeft: flagged ? "2px solid var(--amber)" : "none", borderRadius: flagged ? "0 4px 4px 0" : 0 }}>
            <span style={{ fontWeight: 600, fontSize: 11, color: isPaul ? "var(--brand)" : "var(--t1)", marginRight: 5 }}>{speaker}:</span>
            <span style={{ fontSize: 12, color: "var(--t2)", lineHeight: 1.7 }}>{body}</span>
            {flagged && <span style={{ marginLeft: 8, fontSize: 9, color: "var(--amber)", fontWeight: 600, fontFamily: "var(--fm)" }}>⚠ flagged</span>}
          </div>
        );
      })}
    </div>
  );
}

// ── INTERVIEW SCREEN ──────────────────────────────────────────────────────────
function InterviewScreen({ setup, onEnd }) {
  const [transcript, setTranscript]           = useState("");
  const [suggestions, setSuggestions]         = useState([]);
  const [displayedSuggestions, setDisplayedSuggestions] = useState([]);
  const [inconsistencies, setInconsistencies] = useState([]);
  const [coverage, setCoverage]               = useState({});
  const [liveAnalyzing, setLiveAnalyzing]     = useState(false);
  const [endModal, setEndModal]               = useState(false);
  const [toast, setToast]                     = useState(null);
  const [secs, setSecs]                       = useState(0);
  const [typing, setTyping]                   = useState(false);
  const [phase, setPhase]                     = useState("waiting");
  const [candidateLeft, setCandidateLeft]     = useState(false);
  const [speed]                               = useState(1);
  const typeRef           = useRef(null);
  const speedRef          = useRef(1);
  const posRef            = useRef(0);
  const lastAnalyzedAt    = useRef(0);
  const analyzingRef      = useRef(false);
  const transcriptRef     = useRef(null);
  const addedQuestionsRef = useRef(new Set());

  useEffect(() => { const id = setInterval(() => setSecs(s => s + 1), 1000); return () => clearInterval(id); }, []);

  // Auto-run transcript only once interviewer admits the candidate
  useEffect(() => { if (phase === "live") { setTimeout(() => loadDemo(), 600); } }, [phase]);

  // Detect candidate goodbye to show "left" state
  useEffect(() => {
    if (transcript.includes("Goodbye, Paul") && !typing && !candidateLeft) {
      setTimeout(() => setCandidateLeft(true), 1200);
    }
  }, [transcript, typing]);

  // Scroll transcript to bottom as new text arrives
  useEffect(() => {
    if (transcriptRef.current) transcriptRef.current.scrollTop = transcriptRef.current.scrollHeight;
  }, [transcript]);

  const fmt = s => `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

  const runAnalysis = async (text) => {
    if (analyzingRef.current || !text.trim()) return;
    analyzingRef.current = true; setLiveAnalyzing(true);
    try {
      const raw = await claude(
        `Interview intelligence AI. Analyze and return ONLY this JSON:
{"suggestions":[{"title":"3-4 word topic","question":"Full follow-up question"}],"inconsistencies":[{"title":"3-4 word label","detail":"Full description","phrase":"exact short phrase from transcript that is inconsistent"}],"coverage":{"Competency":0}}
suggestions: 2-3 smart follow-up questions for uncovered areas, each with a short title.
inconsistencies: resume vs interview discrepancies. phrase = the exact words the candidate said that conflict with the resume (3-8 words). Empty array if none found.
coverage: % each competency covered 0-100. Return ONLY JSON.`,
        `Role: ${setup.jobTitle}\nJD: ${setup.jobDescription}\nResume: ${setup.resumeText}\nFramework: ${setup.framework}\nCompetencies: ${setup.competencies.join(", ")}\n\nTranscript:\n${text}`
      );
      const p = JSON.parse(raw);
      // Add ONE new question at a time
      if (p.suggestions) {
        const fresh = p.suggestions.filter(s => s && s.question && !addedQuestionsRef.current.has(s.question));
        if (fresh.length > 0) {
          addedQuestionsRef.current.add(fresh[0].question);
          setDisplayedSuggestions(prev => [...prev, fresh[0]]);
        }
      }
      if (p.inconsistencies) setInconsistencies(p.inconsistencies.filter(i => i && i.detail));
      if (p.coverage)        setCoverage(p.coverage);
    } catch (e) { console.error(e); }
    analyzingRef.current = false; setLiveAnalyzing(false);
  };

  const loadDemo = () => {
    if (typing) { clearInterval(typeRef.current); setTranscript(DEMO_TRANSCRIPT); posRef.current = DEMO_TRANSCRIPT.length; setTyping(false); return; }
    setTranscript(""); setDisplayedSuggestions([]); setInconsistencies([]); setCoverage({});
    addedQuestionsRef.current = new Set();
    posRef.current = 0; lastAnalyzedAt.current = 0; setTyping(true);
    typeRef.current = setInterval(() => {
      const cpt = [2, 4, 7, 12, 20][speedRef.current - 1];
      posRef.current = Math.min(posRef.current + cpt, DEMO_TRANSCRIPT.length);
      const cur = DEMO_TRANSCRIPT.slice(0, posRef.current);
      setTranscript(cur);
      if (cur.length - lastAnalyzedAt.current >= 450) { lastAnalyzedAt.current = cur.length; runAnalysis(cur); }
      if (posRef.current >= DEMO_TRANSCRIPT.length) {
        clearInterval(typeRef.current); setTyping(false);
        if (DEMO_TRANSCRIPT.length - lastAnalyzedAt.current > 80) { lastAnalyzedAt.current = DEMO_TRANSCRIPT.length; runAnalysis(DEMO_TRANSCRIPT); }
      }
    }, 60);
  };

  const copy = text => { navigator.clipboard?.writeText(text); setToast("Copied!"); setTimeout(() => setToast(null), 1500); };
  const hasData = displayedSuggestions.length > 0 || Object.keys(coverage).length > 0;

  // Who is currently speaking based on last dialogue line
  const currentSpeaker = (() => {
    if (!typing) return null;
    const lastPaul = transcript.lastIndexOf("\nPaul:");
    const lastInt  = transcript.lastIndexOf("\nInterviewer:");
    if (lastPaul === -1 && lastInt === -1) return "interviewer";
    return lastPaul > lastInt ? "paul" : "interviewer";
  })();

  // Phrases to highlight in transcript from inconsistencies
  const flaggedPhrases = inconsistencies.map(inc => (typeof inc === "object" ? inc.phrase : null)).filter(Boolean);

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", position: "relative" }}>
      <style>{`
        @keyframes sound-bar { from { height: 4px; } to { height: 20px; } }
        @keyframes pulse-ring { 0%,100% { transform:scale(1); opacity:0.7; } 50% { transform:scale(1.12); opacity:0.25; } }
        @keyframes pulse-slow { 0%,100% { transform:scale(1); opacity:0.5; } 50% { transform:scale(1.08); opacity:0.2; } }
      `}</style>

      {/* ── WAITING ROOM ── */}
      {phase === "waiting" && (
        <div style={{ flex: 1, background: "var(--vid-bg)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 0 }}>
          <div style={{ background: "radial-gradient(ellipse at center, var(--vid-surface) 0%, var(--vid-bg) 100%)", position: "absolute", inset: 0 }} />
          <div style={{ position: "relative", zIndex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 20 }}>
            <div style={{ position: "relative" }}>
              <div style={{ position: "absolute", inset: -14, borderRadius: "50%", border: "2px solid rgba(255,255,255,0.15)", animation: "pulse-slow 3s ease-in-out infinite" }} />
              <div style={{ position: "absolute", inset: -28, borderRadius: "50%", border: "1px solid rgba(255,255,255,0.07)", animation: "pulse-slow 3s ease-in-out infinite 0.8s" }} />
              <img src={PAUL_AVATAR} alt="Paul Emil Johnson" style={{ width: 96, height: 96, borderRadius: "50%", objectFit: "cover", border: "3px solid rgba(255,255,255,0.2)", display: "block", position: "relative", zIndex: 1 }} />
            </div>
            <div style={{ textAlign: "center" }}>
              <div style={{ color: "#f9fafb", fontSize: 18, fontWeight: 600, letterSpacing: "-0.01em", marginBottom: 6 }}>Paul Emil Johnson</div>
              <div style={{ display: "flex", alignItems: "center", gap: 7, justifyContent: "center", color: "#9ca3af", fontSize: 13 }}>
                <div style={{ width: 7, height: 7, borderRadius: "50%", background: "#22c55e", animation: "pulse-slow 1.5s ease-in-out infinite" }} />
                Waiting to be admitted...
              </div>
            </div>
            <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
              <button onClick={() => setPhase("live")} style={{ padding: "13px 36px", borderRadius: 30, background: "#22c55e", border: "none", color: "#fff", fontSize: 14, fontWeight: 600, cursor: "pointer", fontFamily: "var(--f)", letterSpacing: "-0.01em", boxShadow: "0 4px 20px rgba(34,197,94,0.35)" }}>
                Admit to Interview
              </button>
              <div style={{ fontSize: 11, color: "#6b7280", fontFamily: "var(--fm)" }}>Senior Product Designer interview</div>
            </div>
          </div>
        </div>
      )}

      {/* ── LIVE INTERVIEW ── */}
      {phase === "live" && <>
        {/* Slim topbar */}
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "0 18px", height: 44, background: "var(--vid-bg)", borderBottom: "1px solid #1f2937", flexShrink: 0 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 14 }}>
            <LiveDot />
            <span style={{ fontSize: 13, fontWeight: 600, color: "#e5e7eb" }}>{setup.jobTitle} · {setup.candidateName || "Candidate"}</span>
            <div style={{ display: "flex", alignItems: "center", gap: 5, color: "#6b7280", fontSize: 12, fontFamily: "var(--fm)" }}><Clock size={11} /> {fmt(secs)}</div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <Btn variant="ghost" onClick={loadDemo} size="sm" style={{ background: "rgba(255,255,255,0.07)", borderColor: "#374151", color: "#9ca3af" }}>
              {typing ? <><Square size={11} /> Stop</> : <><Play size={11} /> Load Demo</>}
            </Btn>
            <Btn variant="primary" onClick={() => runAnalysis(transcript)} disabled={liveAnalyzing || !transcript.trim()} size="sm">
              {liveAnalyzing ? <><Spinner size={11} color="#fff" /> Analysing...</> : <><Zap size={11} /> Analyse</>}
            </Btn>
          </div>
        </div>

        {/* Body */}
        <div style={{ display: "flex", flex: 1, overflow: "hidden" }}>

          {/* LEFT: Video + transcript */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", minWidth: 0 }}>

            {/* Video area */}
            <div style={{ flex: 1, background: "var(--vid-bg)", position: "relative", overflow: "hidden" }}>
              <div style={{ position: "absolute", inset: 0, background: "radial-gradient(ellipse at center, var(--vid-surface) 0%, var(--vid-bg) 100%)" }} />

              {/* Candidate view */}
              <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
                {candidateLeft ? (
                  /* Candidate left */
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
                    <img src={PAUL_AVATAR} alt="" style={{ width: 96, height: 96, borderRadius: "50%", objectFit: "cover", filter: "grayscale(1)", opacity: 0.4, border: "3px solid rgba(255,255,255,0.1)" }} />
                    <div style={{ color: "#6b7280", fontSize: 14, fontFamily: "var(--fm)" }}>Paul has left the call</div>
                  </div>
                ) : (
                  /* Speaking view */
                  <>
                    <div style={{ position: "relative", marginBottom: 14 }}>
                      <div style={{ position: "absolute", inset: -10, borderRadius: "50%", border: `2px solid ${currentSpeaker === "paul" ? "#22c55e" : "rgba(255,255,255,0.15)"}`, animation: currentSpeaker === "paul" ? "pulse-ring 2.6s ease-in-out infinite" : "none", transition: "border-color 0.4s" }} />
                      <div style={{ position: "absolute", inset: -20, borderRadius: "50%", border: `1px solid ${currentSpeaker === "paul" ? "#22c55e" : "rgba(255,255,255,0.07)"}`, animation: currentSpeaker === "paul" ? "pulse-ring 2.6s ease-in-out infinite 0.6s" : "none", transition: "border-color 0.4s" }} />
                      <img src={PAUL_AVATAR} alt="Paul Emil Johnson" style={{ width: 110, height: 110, borderRadius: "50%", objectFit: "cover", border: `3px solid ${currentSpeaker === "paul" ? "#22c55e" : "rgba(255,255,255,0.15)"}`, display: "block", position: "relative", zIndex: 1, transition: "border-color 0.4s" }} />
                    </div>
                    <div style={{ color: "#f9fafb", fontSize: 16, fontWeight: 600, letterSpacing: "-0.01em", marginBottom: 14 }}>Paul Emil Johnson</div>
                    <div style={{ display: "flex", alignItems: "flex-end", gap: 3, height: 22, opacity: currentSpeaker === "paul" ? 1 : 0.15, transition: "opacity 0.4s" }}>
                      {[0.7,1.1,0.8,1.3,0.9,1.0,0.75,1.2,0.85].map((d, i) => (
                        <div key={i} style={{ width: 3, borderRadius: 2, background: "#22c55e", animation: currentSpeaker === "paul" ? `sound-bar ${d}s ease-in-out ${i * 0.05}s infinite alternate` : "none", height: "8px" }} />
                      ))}
                    </div>
                  </>
                )}
              </div>

              {/* Naimil self-view: avatar style, audio bars when interviewer speaks */}
              <div style={{ position: "absolute", bottom: 68, right: 16, width: 120, height: 88, background: "var(--vid-surface)", borderRadius: 10, border: `2px solid ${currentSpeaker === "interviewer" ? "#22c55e" : "var(--vid-border)"}`, overflow: "hidden", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 4, transition: "border-color 0.4s" }}>
                <img src={NAIMIL_AVATAR} alt="Naimil Shah" style={{ width: 44, height: 44, borderRadius: "50%", objectFit: "cover", objectPosition: "center top", border: "2px solid var(--vid-border)" }} />
                <div style={{ textAlign: "center" }}>
                  <div style={{ fontSize: 10, color: "#f9fafb", fontFamily: "var(--fm)", fontWeight: 500 }}>Naimil Shah</div>
                  {currentSpeaker === "interviewer" && typing ? (
                    <div style={{ display: "flex", alignItems: "flex-end", justifyContent: "center", gap: 2, height: 12, marginTop: 3 }}>
                      {[0.6,1.0,0.7,0.9,0.8].map((d, i) => (
                        <div key={i} style={{ width: 2, borderRadius: 1, background: "#22c55e", animation: `sound-bar ${d}s ease-in-out ${i*0.07}s infinite alternate` }} />
                      ))}
                    </div>
                  ) : (
                    <div style={{ fontSize: 9, color: "#6b7280", fontFamily: "var(--fm)" }}>Interviewer</div>
                  )}
                </div>
              </div>

              {/* Control bar */}
              <div style={{ position: "absolute", bottom: 0, left: 0, right: 0, height: 58, background: "linear-gradient(transparent, rgba(0,0,0,0.8))", display: "flex", alignItems: "center", justifyContent: "center", gap: 12 }}>
                {[{ e: "🎤", tip: "Mute microphone" }, { e: "📷", tip: "Toggle camera" }, { e: "💬", tip: "Open chat" }, { e: "👥", tip: "Participants" }].map(c => (
                  <button key={c.tip} aria-label={c.tip} title={c.tip} style={{ width: 40, height: 40, borderRadius: "50%", background: "rgba(255,255,255,0.12)", border: "none", cursor: "default", fontSize: 16, display: "flex", alignItems: "center", justifyContent: "center", opacity: 0.7 }}>{c.e}</button>
                ))}
                <button aria-label="End interview session" onClick={() => { clearInterval(typeRef.current); setEndModal(true); }} style={{ padding: "10px 20px", borderRadius: 22, background: "#ef4444", border: "none", color: "#fff", fontSize: 12, fontWeight: 600, cursor: "pointer", fontFamily: "var(--f)", display: "flex", alignItems: "center", gap: 6 }}>
                  End Interview
                </button>
              </div>
            </div>

            {/* Transcript strip */}
            <div style={{ height: 240, display: "flex", flexDirection: "column", borderTop: "1px solid var(--b2)", flexShrink: 0 }}>
              <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 14px", borderBottom: "1px solid var(--b1)", background: "#fff", flexShrink: 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                  <div style={{ width: 6, height: 6, borderRadius: "50%", background: "var(--red)", flexShrink: 0 }} />
                  <span style={{ fontSize: 10, fontFamily: "var(--fm)", letterSpacing: "0.12em", textTransform: "uppercase", color: "var(--t3)", fontWeight: 500 }}>Live Transcript</span>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                  {liveAnalyzing
                    ? <div style={{ display: "flex", alignItems: "center", gap: 5 }}><Spinner size={10} /><span style={{ fontSize: 11, fontFamily: "var(--fm)", color: "var(--green)" }}>Analysing...</span></div>
                    : <span style={{ fontSize: 11, fontFamily: "var(--fm)", color: "var(--t4)" }}>{transcript.split(/\s+/).filter(Boolean).length} words</span>
                  }
                </div>
              </div>
              <TranscriptView text={transcript} flaggedPhrases={flaggedPhrases} transcriptRef={transcriptRef} />
            </div>
          </div>

          {/* RIGHT: AI panel */}
          <div style={{ width: 340, overflowY: "auto", display: "flex", flexDirection: "column", background: "var(--s1)", borderLeft: "1px solid var(--b2)" }}>

            {/* 1. AI Suggested Questions */}
            <div style={{ padding: 16, background: "#fff", borderBottom: "1px solid var(--b2)" }}>
              <SectionMark children="AI-Suggested Questions" right={
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  {displayedSuggestions.length > 0 && <div style={{ width: 18, height: 18, borderRadius: "50%", background: "var(--brand)", color: "#fff", fontSize: 10, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "var(--fm)" }}>{displayedSuggestions.length}</div>}
                  {liveAnalyzing && <div style={{ display: "flex", alignItems: "center", gap: 5 }}><Spinner size={10} /><span style={{ fontSize: 9, fontFamily: "var(--fm)", color: "var(--green)" }}>updating</span></div>}
                </div>
              } />
              {displayedSuggestions.length === 0
                ? <div className="ds-empty"><div className="ds-empty-icon"><Zap size={16} style={{ color: "var(--t3)" }} /></div><div className="ds-empty-title">Waiting for transcript</div><div className="ds-empty-sub">Questions generate after the first 30 seconds of conversation</div></div>
                : <div style={{ maxHeight: 260, overflowY: "auto", display: "flex", flexDirection: "column", gap: 8 }}>
                    {displayedSuggestions.map((sq, i) => {
                      const title = typeof sq === "object" ? sq.title : `Question ${i+1}`;
                      const question = typeof sq === "object" ? sq.question : sq;
                      return (
                        <div key={i} className="ds-fadein" style={{ border: "1px solid var(--b2)", borderLeft: "3px solid var(--brand)", borderRadius: "var(--r-sm)", padding: "10px 12px", background: "var(--s2)" }}>
                          <div style={{ fontSize: 10, fontFamily: "var(--fm)", color: "var(--brand)", letterSpacing: "0.08em", marginBottom: 5, fontWeight: 600 }}>{title.toUpperCase()}</div>
                          <div style={{ fontSize: 12, color: "var(--t2)", lineHeight: 1.6 }}>{question}</div>
                        </div>
                      );
                    })}
                  </div>
              }
            </div>

            {/* 2. Inconsistency Monitor */}
            <div style={{ padding: 16, background: "#fff", borderBottom: "1px solid var(--b2)" }}>
              <SectionMark children={inconsistencies.length ? `${inconsistencies.length} Inconsistenc${inconsistencies.length > 1 ? "ies" : "y"} Detected` : "Inconsistency Monitor"} color={inconsistencies.length ? "var(--amber)" : undefined} right={liveAnalyzing && <div style={{ display: "flex", alignItems: "center", gap: 5 }}><Spinner size={10} /><span style={{ fontSize: 9, fontFamily: "var(--fm)", color: "var(--green)" }}>scanning</span></div>} />
              {inconsistencies.length === 0
                ? <div className="ds-empty"><div className="ds-empty-icon"><AlertTriangle size={16} style={{ color: "var(--t3)" }} /></div><div className="ds-empty-title">Monitoring responses</div><div className="ds-empty-sub">Flags appear when claims don't match the resume</div></div>
                : <div style={{ maxHeight: 220, overflowY: "auto", display: "flex", flexDirection: "column", gap: 8 }}>
                    {inconsistencies.map((inc, i) => {
                      const title = typeof inc === "object" ? inc.title : `Flag ${i+1}`;
                      const detail = typeof inc === "object" ? inc.detail : inc;
                      return (
                        <div key={i} className="ds-flag-new" style={{ background: "var(--amber-lo)", border: "1px solid var(--amber-md)", borderLeft: "3px solid var(--amber)", borderRadius: "0 var(--r-sm) var(--r-sm) 0", padding: "10px 12px" }}>
                          <div style={{ fontSize: 9, fontFamily: "var(--fm)", color: "var(--amber)", letterSpacing: "0.08em", marginBottom: 5, fontWeight: 600, display: "flex", alignItems: "center", gap: 5 }}><AlertTriangle size={9} /> {title.toUpperCase()}</div>
                          <div style={{ fontSize: 12, color: "var(--t1)", lineHeight: 1.6 }}>{detail}</div>
                        </div>
                      );
                    })}
                  </div>
              }
            </div>

            {/* 3. Coverage Tracker */}
            <div style={{ padding: 16, background: "#fff" }}>
              <SectionMark children="Coverage Tracker" right={liveAnalyzing && <div style={{ display: "flex", alignItems: "center", gap: 5 }}><Spinner size={10} /><span style={{ fontSize: 9, fontFamily: "var(--fm)", color: "var(--green)" }}>updating</span></div>} />
              {setup.competencies.map(c => {
                const pct = Math.round(coverage[c] ?? 0);
                const { bar, color } = GradBar({ pct });
                return (
                  <div key={c} style={{ marginBottom: 12 }}>
                    <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 6 }}>
                      <span style={{ fontSize: 12, color: "var(--t2)" }}>{c}</span>
                      <span style={{ fontSize: 11, fontFamily: "var(--fm)", color, transition: "color 0.5s" }}>{pct}%</span>
                    </div>
                    {bar}
                  </div>
                );
              })}
              {!hasData && <div className="ds-empty"><div className="ds-empty-icon"><Activity size={16} style={{ color: "var(--t3)" }} /></div><div className="ds-empty-sub">Bars fill in as competencies are addressed</div></div>}
            </div>
          </div>
        </div>

        {/* End-of-interview modal */}
        {endModal && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(10,14,23,0.82)", backdropFilter: "blur(6px)", WebkitBackdropFilter: "blur(6px)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 200 }}>
            <div style={{ background: "#fff", borderRadius: 20, padding: "40px 36px", maxWidth: 400, width: "90%", textAlign: "center", boxShadow: "0 32px 80px rgba(0,0,0,0.45)" }} className="ds-fadein">
              <div style={{ display: "flex", justifyContent: "center", marginBottom: 20 }}>
                <CoralMark size={52} fill="#F2416A" />
              </div>
              <div style={{ fontSize: 20, fontWeight: 700, color: "#111827", letterSpacing: "-0.02em", marginBottom: 10 }}>
                The interview has ended
              </div>
              <p style={{ fontSize: 14, color: "#6b7280", lineHeight: 1.75, marginBottom: 28 }}>
                Your evaluation report is ready.
              </p>
              <button className="ds-btn ds-btn-primary" onClick={() => onEnd(transcript)} style={{ padding: "12px 32px", fontSize: 14, width: "100%", justifyContent: "center" }}>
                View Report
              </button>
            </div>
          </div>
        )}
      </>}

      {toast && <div style={{ position: "fixed", bottom: 20, right: 20, background: "var(--t1)", color: "#fff", padding: "8px 16px", borderRadius: "var(--r-sm)", fontSize: 12, fontFamily: "var(--fm)", zIndex: 999 }}>{toast}</div>}
    </div>
  );
}

// ── REPORT SCREEN ─────────────────────────────────────────────────────────────
function ReportScreen({ setup, transcript, onReset }) {
  const [report, setReport]   = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  useEffect(() => { generate(); }, []);

  const generate = async () => {
    setLoading(true); setError(null);
    try {
      const trimmed = transcript.length > 3000 ? "…" + transcript.slice(-3000) : transcript || "(No transcript)";
      const raw = await claude(
        `Senior HR analyst. Return ONLY valid JSON:
{"candidateName":"string","overallScore":7,"recommendation":"PROCEED","summary":"string","competencyScores":[{"name":"string","score":4,"notes":"string"}],"inconsistencies":["string"],"strengths":["string"],"concerns":["string"],"nextSteps":"string"}
recommendation = PROCEED | HOLD | REJECT. Return ONLY the JSON object.`,
        `Role: ${setup.jobTitle}\nJD: ${setup.jobDescription}\nResume: ${setup.resumeText}\nFramework: ${setup.framework}\nCompetencies: ${setup.competencies.join(", ")}\nTranscript:\n${trimmed}`,
        2000
      );
      setReport(JSON.parse(raw));
    } catch (e) { setError(e.message || "Unknown error"); }
    setLoading(false);
  };

  if (loading) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "100%", flexDirection: "column", gap: 16 }}>
      <div style={{ position: "relative", width: 44, height: 44 }}>
        <div style={{ position: "absolute", inset: 0, border: "2px solid var(--b2)", borderRadius: "50%" }} />
        <div style={{ position: "absolute", inset: 0, border: "2px solid transparent", borderTopColor: "var(--brand)", borderRadius: "50%", animation: "ds-spin 0.8s linear infinite" }} />
        <Activity size={16} style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%,-50%)", color: "var(--brand)" }} />
      </div>
      <p style={{ fontSize: 13, fontFamily: "var(--fm)", color: "var(--t3)" }}>Generating evaluation report…</p>
    </div>
  );

  if (error || !report) return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", height: "100%", flexDirection: "column", gap: 14 }}>
      <XCircle size={36} style={{ color: "var(--red)" }} />
      <p style={{ fontSize: 15, fontWeight: 600 }}>Report generation failed</p>
      {error && <p style={{ fontSize: 12, fontFamily: "var(--fm)", color: "var(--t3)", maxWidth: 360, textAlign: "center", lineHeight: 1.7 }}>{error}</p>}
      <div style={{ display: "flex", gap: 10, marginTop: 4 }}>
        <Btn variant="primary" onClick={generate}><RotateCcw size={13} /> Retry</Btn>
        <Btn variant="ghost" onClick={onReset}>← New Interview</Btn>
      </div>
    </div>
  );

  const recCfg = {
    PROCEED: { bg: "var(--green-lo)", text: "var(--green)", border: "var(--green-md)", icon: <CheckCircle2 size={14} />, label: "Recommended to Hire" },
    HOLD:    { bg: "var(--amber-lo)", text: "var(--amber)", border: "var(--amber-md)", icon: <Clock size={14} />,         label: "Hold for Review"    },
    REJECT:  { bg: "var(--red-lo)",   text: "var(--red)",   border: "var(--red-md)",   icon: <XCircle size={14} />,       label: "Not Recommended"  },
  };
  const rec = recCfg[report.recommendation] || recCfg.HOLD;
  const scoreColor = n => n >= 4 ? "var(--green)" : n >= 3 ? "var(--amber)" : "var(--red)";
  const scoreGrad  = n => n >= 4 ? "linear-gradient(90deg,#059669,#34d399)" : n >= 3 ? "linear-gradient(90deg,#b45309,#fbbf24)" : "linear-gradient(90deg,#9f1239,#fb7185)";

  return (
    <div style={{ minHeight: "calc(100vh - 56px)" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "14px 24px", borderBottom: "1px solid var(--b2)", background: "#fff" }}>
        <div>
          <h2 style={{ fontSize: 17, fontWeight: 700, letterSpacing: "-0.01em" }}>Interview Report</h2>
          <p style={{ fontSize: 12, color: "var(--t3)", marginTop: 2 }}>{report.candidateName} · {setup.jobTitle}</p>
        </div>
        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <div style={{ display: "inline-flex", alignItems: "center", gap: 7, padding: "7px 16px", borderRadius: 99, fontSize: 13, fontWeight: 600, background: rec.bg, color: rec.text, border: `1px solid ${rec.border}` }}>{rec.icon} {rec.label}</div>
          <Btn variant="ghost" onClick={onReset} size="sm">← New Interview</Btn>
        </div>
      </div>

      <div style={{ maxWidth: 980, margin: "0 auto", padding: "24px", display: "flex", flexDirection: "column", gap: 16 }}>
        <Card>
          <div style={{ display: "flex", alignItems: "center", gap: 20, marginBottom: 18 }}>
            <ScoreRing score={report.overallScore} color={report.overallScore >= 7 ? "var(--green)" : report.overallScore >= 5 ? "var(--amber)" : "var(--red)"} />
            <div style={{ flex: 1 }}>
              <div style={{ display: "inline-flex", alignItems: "center", gap: 7, padding: "8px 16px", borderRadius: 99, fontSize: 13, fontWeight: 700, background: rec.bg, color: rec.text, border: `1px solid ${rec.border}`, marginBottom: 14 }}>
                {rec.icon} {rec.label}
              </div>
              <div style={{ position: "relative", height: 6, background: "var(--b2)", borderRadius: 4, marginBottom: 6 }}>
                <div style={{ position: "absolute", left: "60%", top: -3, bottom: -3, width: 2, background: "var(--b3)", borderRadius: 1 }} />
                <div style={{ height: "100%", width: `${report.overallScore * 10}%`, background: "linear-gradient(90deg,#fbbf24,#34d399)", borderRadius: 4, transition: "width 0.9s var(--ease)" }} />
              </div>
              <div style={{ display: "flex", justifyContent: "space-between" }}>
                <span style={{ fontSize: 10, fontFamily: "var(--fm)", color: "var(--t4)" }}>0</span>
                <span style={{ fontSize: 10, fontFamily: "var(--fm)", color: "var(--t3)" }}>Hire threshold · 6</span>
                <span style={{ fontSize: 10, fontFamily: "var(--fm)", color: "var(--t4)" }}>10</span>
              </div>
            </div>
          </div>

          <div style={{ borderTop: "1px solid var(--b1)", paddingTop: 14 }}>
            <SectionMark>Executive Summary</SectionMark>
            <p style={{ fontSize: "var(--tx-base)", color: "var(--t1)", lineHeight: 1.85 }}>{report.summary}</p>
          </div>
        </Card>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
          <Card>
            <SectionMark>Competency Evaluation</SectionMark>
            {(report.competencyScores || []).map(cs => (
              <div key={cs.name} style={{ marginBottom: 14 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 6 }}>
                  <span style={{ fontSize: "var(--tx-base)" }}>{cs.name}</span>
                  <div style={{ display: "flex", gap: 4 }}>
                    {[1,2,3,4,5].map(i => <div key={i} style={{ width: 9, height: 9, borderRadius: "50%", background: i <= cs.score ? scoreColor(cs.score) : "#E5E7EB" }} />)}
                  </div>
                </div>
                {cs.notes && <p style={{ fontSize: "var(--tx-xs)", color: "var(--t3)", lineHeight: 1.5 }}>{cs.notes}</p>}
              </div>
            ))}
          </Card>

          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            <Card style={{ flex: 1 }}>
              <SectionMark color="var(--green)">✓ Strengths</SectionMark>
              {(report.strengths || []).map((s, i) => <div key={i} style={{ fontSize: 13, color: "var(--t2)", paddingLeft: 11, borderLeft: "2px solid var(--green-md)", marginBottom: 8, lineHeight: 1.6 }}>{s}</div>)}
            </Card>
            <Card style={{ flex: 1 }}>
              <SectionMark color="var(--amber)">⚠ Concerns</SectionMark>
              {(report.concerns || []).map((c, i) => <div key={i} style={{ fontSize: 13, color: "var(--t2)", paddingLeft: 11, borderLeft: "2px solid var(--amber-md)", marginBottom: 8, lineHeight: 1.6 }}>{c}</div>)}
            </Card>
          </div>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 16 }}>
          <Card>
            <SectionMark color={(report.inconsistencies || []).length ? "var(--amber)" : undefined}>{(report.inconsistencies || []).length ? "⚠ Inconsistencies Found" : "Inconsistencies"}</SectionMark>
            {!(report.inconsistencies || []).length
              ? <p style={{ fontSize: 12, color: "var(--t4)", fontStyle: "italic" }}>No significant inconsistencies detected.</p>
              : report.inconsistencies.map((inc, i) => (
                  <div key={i} style={{ background: "var(--amber-lo)", border: "1px solid var(--amber-md)", borderRadius: "var(--r-sm)", padding: "10px 12px", marginBottom: 8 }}>
                    <div style={{ fontSize: 9, fontFamily: "var(--fm)", color: "var(--amber)", letterSpacing: "0.1em", marginBottom: 5 }}>FLAG #{i + 1}</div>
                    <div style={{ fontSize: 12, color: "var(--t1)", lineHeight: 1.6 }}>{inc}</div>
                  </div>
                ))
            }
          </Card>
          <Card>
            <SectionMark>Recommended Next Steps</SectionMark>
            <p style={{ fontSize: 13, color: "var(--t2)", lineHeight: 1.8 }}>{report.nextSteps}</p>
          </Card>
        </div>
      </div>
    </div>
  );
}

// ── BROWSER CHROME ───────────────────────────────────────────────────────────
function BrowserChrome({ tabs, activeIdx, onTabClick, onTabClose, url, children }) {
  return (
    <div style={{ background: "linear-gradient(160deg,#dce4f0,#cdd7e8)", height: "100vh", padding: "14px 14px 0", boxSizing: "border-box", display: "flex", flexDirection: "column" }}>
      <div style={{ flex: 1, background: "#fff", borderRadius: "12px 12px 0 0", boxShadow: "0 12px 56px rgba(0,0,0,0.22)", overflow: "hidden", display: "flex", flexDirection: "column", minHeight: 0 }}>

        {/* Top chrome */}
        <div style={{ background: "#f1f3f4", flexShrink: 0 }}>

          {/* Traffic lights + drag area */}
          <div style={{ padding: "10px 14px 0", display: "flex", alignItems: "center", gap: 6 }}>
            {[["#FF5F57","#E0443E"],["#FEBC2E","#D4A017"],["#28C840","#1DAF2F"]].map(([bg, border], i) => (
              <div key={i} style={{ width: 12, height: 12, borderRadius: "50%", background: bg, border: `1px solid ${border}` }} />
            ))}
          </div>

          {/* Tab bar */}
          <div style={{ display: "flex", alignItems: "flex-end", padding: "6px 12px 0", gap: 1 }}>
            {tabs.map((tab, i) => {
              const isActive = i === activeIdx;
              return (
                <div key={tab.id} onClick={() => onTabClick(i)} style={{ display: "flex", alignItems: "center", gap: 7, padding: "7px 12px 7px 10px", minWidth: 140, maxWidth: 240, background: isActive ? "#fff" : "transparent", borderRadius: "8px 8px 0 0", borderTop: isActive ? "1px solid #dadce0" : "none", borderLeft: isActive ? "1px solid #dadce0" : "none", borderRight: isActive ? "1px solid #dadce0" : "none", marginBottom: -1, cursor: "pointer", zIndex: isActive ? 1 : 0, position: "relative" }}>
                  <CoralMark size={13} fill="#F2416A" />
                  <span style={{ fontSize: 12, color: isActive ? "#202124" : "#5f6368", flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", fontFamily: "var(--f)", fontWeight: isActive ? 500 : 400 }}>{tab.title}</span>
                  {tabs.length > 1 && (
                    <button onClick={e => { e.stopPropagation(); onTabClose(i); }} style={{ background: "none", border: "none", color: "#9aa0a6", cursor: "pointer", fontSize: 15, lineHeight: 1, padding: "1px 2px", display: "flex", alignItems: "center", borderRadius: 3, flexShrink: 0 }}>×</button>
                  )}
                </div>
              );
            })}
            <div style={{ padding: "7px 10px", color: "#5f6368", cursor: "pointer", fontSize: 18, lineHeight: 1 }}>+</div>
          </div>

          {/* Address bar */}
          <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 14px 9px", borderTop: "1px solid #dadce0" }}>
            {["←","→","↻"].map(s => (
              <button key={s} style={{ background: "none", border: "none", color: "#9aa0a6", fontSize: 15, fontFamily: "monospace", padding: "3px 5px", cursor: "default", borderRadius: 4 }}>{s}</button>
            ))}
            <div style={{ flex: 1, background: "#fff", border: "1px solid #dadce0", borderRadius: 20, padding: "5px 14px", display: "flex", alignItems: "center", gap: 8, fontSize: 13, fontFamily: "var(--f)", boxShadow: "0 1px 3px rgba(0,0,0,0.07)" }}>
              <span style={{ fontSize: 11, color: "#1a73e8" }}>🔒</span>
              <span style={{ color: "#3c4043", letterSpacing: "-0.01em" }}>{url}</span>
            </div>
            <div style={{ width: 22, height: 22, borderRadius: "50%", overflow: "hidden", border: "1.5px solid #dadce0", flexShrink: 0 }}>
              <img src={NAIMIL_AVATAR} style={{ width: "100%", height: "100%", objectFit: "cover" }} alt="Naimil Shah" />
            </div>
          </div>
        </div>

        {/* Browser content */}
        <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden", background: "#fff" }}>
          {children}
        </div>
      </div>
    </div>
  );
}

// ── ROOT ──────────────────────────────────────────────────────────────────────
export default function App() {
  const [tabs, setTabs] = useState([
    { id: 1, title: "New Interview · Interview Intelligence", url: "app.coralai.io/interviews/new", screen: "setup", setup: null, transcript: "", reportData: null, reportGenerating: false, reportError: null, subTab: "intelligence" }
  ]);
  const [activeTabId, setActiveTabId] = useState(1);
  const nextId = useRef(2);

  const activeTab = tabs.find(t => t.id === activeTabId) || tabs[0];
  const activeIdx = tabs.findIndex(t => t.id === activeTabId);

  const openInterviewTab = (setupData) => {
    const id = nextId.current++;
    const newTab = { id, title: `Live Interview · ${setupData.candidateName}`, url: "app.coralai.io/interviews/live", screen: "interview", setup: setupData, transcript: "" };
    setTabs(prev => [...prev, newTab]);
    setActiveTabId(id);
  };

  const updateTab = (id, updates) => setTabs(prev => prev.map(t => t.id === id ? { ...t, ...updates } : t));

  const closeTab = (idx) => {
    const id = tabs[idx].id;
    const newTabs = tabs.filter((_, i) => i !== idx);
    if (!newTabs.length) return;
    setTabs(newTabs);
    if (activeTabId === id) setActiveTabId(newTabs[Math.max(0, idx - 1)].id);
  };

  // Use pre-generated report instantly — no API call needed for the demo
  const generateReport = (_setupData, _transcript) => {
    setTabs(prev => prev.map(t => t.id === 1 ? { ...t, reportData: DEMO_REPORT, reportGenerating: false } : t));
  };

  // Called when "View Report" is clicked in the interview modal
  const handleInterviewEnd = (interviewTabId, setupData, transcript) => {
    // Flip Tab 1 into summary mode + start generating
    setTabs(prev =>
      prev
        .filter(t => t.id !== interviewTabId)          // close interview tab
        .map(t => t.id === 1 ? { ...t, reportGenerating: true, reportData: null, reportError: null, subTab: "summary" } : t)
    );
    setActiveTabId(1);
    generateReport(setupData, transcript);
  };

  return (
    <>
      <style>{DS}</style>
      <BrowserChrome
        tabs={tabs}
        activeIdx={activeIdx}
        onTabClick={i => setActiveTabId(tabs[i].id)}
        onTabClose={closeTab}
        url={activeTab?.url || ""}
      >
        {/* Sidebar + content side-by-side */}
        <div style={{ display: "flex", flex: 1, overflow: "hidden" }}>
          {activeTab?.screen !== "interview" && <Sidebar activeNav="Interviews" />}

          {/* Main content pane */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", overflow: "hidden" }}>
            {activeTab?.screen === "setup" && (
              <div style={{ flex: 1, overflowY: "auto", overflowX: "hidden" }}>
                <SetupScreen
                  onStart={openInterviewTab}
                  reportData={activeTab?.reportData}
                  reportGenerating={activeTab?.reportGenerating}
                  reportError={activeTab?.reportError}
                  activeSubTab={activeTab?.subTab}
                  onSubTabChange={tab => updateTab(1, { subTab: tab })}
                />
              </div>
            )}

            {activeTab?.screen === "interview" && activeTab.setup && (
              <InterviewScreen
                setup={activeTab.setup}
                onEnd={transcript => handleInterviewEnd(activeTabId, activeTab.setup, transcript)}
              />
            )}
          </div>
        </div>
      </BrowserChrome>
    </>
  );
}
